export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  Body: string
  From: string
  MessageSid: string
}

export interface HandleResult {
  messageId: string
  channel: string
  slackResponse: {
    ok: boolean
    channel: string
    ts: string
  }
}

const SALES_KEYWORDS = /pricing|quote|demo/i
const SLACK_API_URL = 'https://slack.com/api/chat.postMessage'

export async function handle(
  payload: TwilioSmsPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.Body) {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From) {
    throw new Error('Missing required field: From')
  }
  if (!payload.MessageSid) {
    throw new Error('Missing required field: MessageSid')
  }

  // Determine target channel based on message content
  const channel = SALES_KEYWORDS.test(payload.Body) ? '#sales' : '#support'

  // Prepare Slack API request
  const requestBody = {
    channel,
    text: payload.Body
  }

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${SLACK_API_URL}`)
  }

  const slackResponse = await response.json() as { ok: boolean; channel: string; ts: string }

  return {
    messageId: payload.MessageSid,
    channel,
    slackResponse
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, TwilioSmsPayload, ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('#sales')
    expect(result.messageId).toBe(SOURCE_EXAMPLE.MessageSid)
  })
})

describe('handle', () => {
  it('routes pricing inquiry to #sales', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === TARGET_ENDPOINTS[0].url
        ? jsonResponse({ ok: true, channel: '#sales', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioSmsPayload = {
      Body: 'Need pricing for enterprise plan',
      From: '+15551234567',
      MessageSid: 'SM1234567890'
    }

    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })

    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Need pricing for enterprise plan' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test')
  })

  it('routes quote request to #sales', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === TARGET_ENDPOINTS[0].url
        ? jsonResponse({ ok: true, channel: '#sales', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioSmsPayload = {
      Body: 'Please send me a quote',
      From: '+15551234567',
      MessageSid: 'SM1234567891'
    }

    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })

    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Please send me a quote' })
  })

  it('routes demo request to #sales', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === TARGET_ENDPOINTS[0].url
        ? jsonResponse({ ok: true, channel: '#sales', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioSmsPayload = {
      Body: 'Can I schedule a demo?',
      From: '+15551234567',
      MessageSid: 'SM1234567892'
    }

    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })

    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Can I schedule a demo?' })
  })

  it('routes general inquiry to #support', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === TARGET_ENDPOINTS[0].url
        ? jsonResponse({ ok: true, channel: '#support', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioSmsPayload = {
      Body: 'How do I reset my password?',
      From: '+15551234567',
      MessageSid: 'SM1234567893'
    }

    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })

    expect(result.channel).toBe('#support')
    expect(calls[0].json).toEqual({ channel: '#support', text: 'How do I reset my password?' })
  })

  it('throws on missing Body field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { From: '+15551234567', MessageSid: 'SM123' } as unknown as TwilioSmsPayload

    await expect(handle(payload, { slackBotToken: 'xoxb-test', fetch })).rejects.toThrow('Missing required field: Body')
  })

  it('throws on missing From field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { Body: 'Hello', MessageSid: 'SM123' } as unknown as TwilioSmsPayload

    await expect(handle(payload, { slackBotToken: 'xoxb-test', fetch })).rejects.toThrow('Missing required field: From')
  })

  it('throws on missing MessageSid field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { Body: 'Hello', From: '+15551234567' } as unknown as TwilioSmsPayload

    await expect(handle(payload, { slackBotToken: 'xoxb-test', fetch })).rejects.toThrow('Missing required field: MessageSid')
  })

  it('throws on non-2xx Slack response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))

    const payload: TwilioSmsPayload = {
      Body: 'Pricing inquiry',
      From: '+15551234567',
      MessageSid: 'SM1234567894'
